#!/bin/bash
set -e
echo "Installing ZCORP AI project..."
TMP_ZIP="/tmp/zcorp-ai.zip"
base64 -d > "$TMP_ZIP" <<'ZCORPZIP'

ZCORPZIP
mkdir -p /tmp/zcorp-ai-extract
unzip -q -o "$TMP_ZIP" -d /tmp/zcorp-ai-extract
SRC="/tmp/zcorp-ai-extract/zcorp-ai"
cp -R "$SRC"/. .
rm -rf /tmp/zcorp-ai-extract "$TMP_ZIP"
echo "Done. The ZCORP AI project files are now in this repository."
